cted>{{ data_get($site,'address.state') }}</option>@endif</select></div><div class="col-md-3"><select class="form-select" name="sites[{{ $i }}][address][district]" data-india-district data-label="Site district"><option value="">Select district</option>@if(filled(data_get($site,'address.district')))<option value="{{ data_get($site,'address.district') }}" selected>{{ data_get($site,'address.district') }}</option>@endif</select></div><div class="col-md-3"><input class="form-control" name="sites[{{ $i }}][address][city]" value="{{ data_get($site,'address.city') }}" placeholder="City"></div><div class="col-md-3"><input class="form-control" name="sites[{{ $i }}][address][pin]" value="{{ data_get($site,'address.pin') }}" placeholder="PIN code" inputmode="numeric" maxlength="6" pattern="[0-9]{6}"></div><div class="col-md-3"><input class="form-control" name="sites[{{ $i }}][contacts][phone]" value="{{ data_get($site,'contacts.phone') }}" placeholder="Phone"></div></div></div>@endforeach</div></div>
