    <template id="siteTemplate"><div class="nx-repeat-card site-card"><div class="d-flex justify-content-between"><strong>New site</strong><button type="button" class="btn btn-sm text-danger remove-site">Remove</button></div><div class="row g-2 mt-1"><div class="col-md-3"><input class="form-control" data-name="site_id" placeholder="Site ID" data-v="required_with:name|unique_in:site_ids" maxlength="60"></div><div class="col-md-2"><input class="form-control" data-name="code" placeholder="Code" data-v="required_with:name|unique_in:site_codes|alpha_dash" maxlength="50"></div><div class="col-md-4"><input class="form-control" data-name="name" placeholder="Site name"></div><div class="col-md-3"><select class="form-select" data-name="type"><option value="additional_place">Additional Place</option><option value="warehouse">Warehouse</option><option value="workshop">Workshop</option><option value="counter">Counter</option><option value="office">Office</option></select></div><div class="col-md-6"><input class="form-control" data-name="address][line1" placeholder="Complete address"></div><div class="col-md-3"><select class="form-select" data-name="address][state" data-india-state data-label="Site state"><option value="">Select state</option></select></div><div class="col-md-3"><select class="form-select" data-name="address][district" data-india-district data-label="Site district"><option value="">Select district</option></select></div><div class="col-md-3"><input class="form-control" data-name="address][city" placeholder="City"></div><div class="col-md-3"><input class="form-control" data-name="address][pin" placeholder="PIN code" inputmode="numeric" maxlength="6" pattern="[0-9]{6}"></div><div class="col-md-3"><input class="form-control" data-name="contacts][phone" placeholder="Phone"></div></div></div></template>
    @push('scripts')<script>document.addEventListener('DOMContentLoaded',()=>{const panes=[...document.querySelectorAll('.nx-step-pane')],steps=[...document.querySelectorAll('.nx-step')],back=document.getElementById('companyBack'),next=document.getElementById('companyNext'),submit=document.getElementById('companySubmit');let current=0;function show(i){current=Math.max(0,Math.min(i,panes.length-1));panes.forEach((p,x)=>p.classList.toggle('active',x===current));steps.forEach((s,x)=>s.classList.toggle('active',x===current));back.disabled=!current;next.classList.toggle('d-none',current===panes.length-1);submit.classList.toggle('d-none',current!==panes.length-1)}steps.forEach((s,i)=>s.onclick=()=>show(i));back.onclick=()=>show(current-1);next.onclick=()=>{if(!NxValidate.validateContainer(panes[current])){steps[current].classList.add('error');return}steps[current].classList.remove('error');show(current+1)};document.getElementById('companyWizard').addEventListener('nx:reveal',e=>{show(Number(e.detail.step)-1);e.preventDefault()});const list=document.getElementById('siteList');document.getElementById('addSite').onclick=()=>{const i=list.querySelectorAll('.site-card').length,node=document.getElementById('siteTemplate').content.cloneNode(true);node.querySelectorAll('[data-name]').forEach(el=>el.name=`sites[${i}][${el.dataset.name}]`);list.append(node)};list.addEventListener('click',e=>{if(e.target.closest('.remove-site'))e.target.closest('.site-card').remove()});show(0)});</script>@endpush
</x-app-layout>
